"""Build the experiment notebook without the local report project."""
from common import HERE
import nbformat as nbf

def main():
    cells=[]
    def md(s):cells.append(nbf.v4.new_markdown_cell(s))
    def code(s):cells.append(nbf.v4.new_code_cell(s))
    md('# Team 11: feedback controls and final evaluation\n\n**November 20, 2026.** We classify the current published appeal as affirmed (0) or reversed/vacated (1). This is not forecasting a future judgment. The notebook explains and verifies the completed experiments; saved final-test predictions are read only.\n\nReview confirmation: **Yinkui Yu, November 19, 2026**, with no additional family corrections. Original provisional artifacts are preserved. The new reviewed release records the scope and source labels explicitly.')
    code("from pathlib import Path\nimport sys, json, hashlib, subprocess\nimport numpy as np\nimport pandas as pd\nfrom IPython.display import display, Markdown, Image\nHERE = Path.cwd()\nif not (HERE / 'common.py').exists():\n    HERE = HERE / 'experiments' / 'feedback_controls'\nassert (HERE / 'common.py').exists(), 'Start in the repository or notebook directory.'\nsys.path.insert(0, str(HERE))\nfrom common import read, records, load_rows, SELECTED_C, SEEDS, digest\nfrom modeling import estimator, scores\nR = HERE / 'results'\nF = HERE / 'final'\nmetrics = pd.DataFrame(read(R / 'metrics.json'))\nfinal = pd.DataFrame(read(F / 'results/metrics.json'))\ndisplay(pd.DataFrame(read(R / 'completion_status.json')))")
    md('## 1. Frozen data and review provenance\n\nWe exclude all 54 disputed B/C eligibility records and remove the approved Mann duplicate NY-6112018. The primary development replication keeps the earlier 279/42 split; deduplication and the final fit use 278 training rows. Test labels were fixed before any final predictions. Known same-family records stay together, but this is not a claim that every remaining source record is a unique decision. No labels, selected evidence quotes, case IDs or reviewer metadata enter the text features.')
    code("protocol = read(F / 'inputs/protocol.json')\nreview = read(F / 'inputs/human_review_confirmation.json')\nfor name, expected in protocol['sha256'].items():\n    assert digest((F / 'inputs' / name).read_bytes()) == expected\nmanifest = pd.DataFrame(records(F / 'inputs/reviewed_manifest.jsonl'))\ndisplay(pd.crosstab(manifest.period, manifest.label).rename(columns={0:'Affirmed',1:'Reversed/vacated'}))\nprint('Review:', review['reviewer'], review['review_date'])\nprint(review['scope_interpretation'])\nassert manifest.groupby('family_id').period.nunique().max() == 1")
    md('## 2. Preprocessing and matched interventions\n\nFULL removes publication material using the inherited batch-specific cleaner. MASKED uses the exact earlier A versus B/C policies. Each random control deletes exactly the same number of whitespace-delimited words as MASKED, with seeds 11, 23, 37, 51 and 71. This matches word quantity, **not** semantic content or WordPiece-token counts. REVISED applies the approved training-audit corrections uniformly, without case-ID exceptions. Some residual outcome language remains; this is a sensitivity experiment, not a certified outcome-free representation.')
    code("variants = records(HERE / 'inputs/variants.jsonl')\nquality = records(HERE / 'inputs/quality_v1/variants.jsonl')\nfor row in variants:\n    for seed in SEEDS:\n        assert len(row['texts'][f'RANDOM_{seed}'].split()) == len(row['texts']['MASKED'].split())\nfor row in quality:\n    for seed in SEEDS:\n        assert len(row['texts'][f'REVISED_RANDOM_{seed}'].split()) == len(row['texts']['REVISED'].split())\ndisplay(pd.DataFrame(read(R / 'component_retention.json')))\nprint('All development random-removal budgets verified.')")
    md('## 3. Two-class masking audit\n\nFour flagged training opinions (two from each class) motivated the frozen revision. Four validation opinions, also two per class, were checked afterward without retuning. The audit distinguishes original judicial reasoning, prior rulings and citations from the current disposition. It records failures instead of claiming a perfect mask.')
    code("audit = read(R / 'two_class_mask_audit.json')\ndisplay(pd.DataFrame(audit['cases'])[['case_id','period','label','preserved_kind','preserved_in_original_mask','preserved_in_revision','technical_review_note']])\nprint('Residual issues:', *audit['unresolved_findings'], sep='\\n- ')")
    md('## 4. Models, training-only choices and frozen encoder\n\nLR and SVM use training-fitted unigram/bigram TF-IDF (`min_df=2`, maximum 30,000 features) with balanced class weights. The previous training-family CV selected C=10 for both lexical models and C=0.1 for LEGAL-BERT LR. Those settings are fixed across primary text variants; C=1 is a separate sensitivity check.\n\nThe pinned frozen LEGAL-BERT checkpoint is processed in non-overlapping chunks of 510 content tokens plus special tokens. We average the last hidden layer over content tokens, excluding padding and special tokens, then combine chunks with token-count weights. Standardization is fitted only on training vectors. No encoder fine-tuning was done. First-chunk-only uses the same tokenization and classifier settings.')
    code("index = read(R / 'embeddings/index.json')\nfor name, expected in index['sha256'].items():\n    assert digest((R / 'embeddings' / name).read_bytes()) == expected\nprint(index['settings']['encoder'])\nprint('Fixed C:', SELECTED_C)\ndisplay(pd.DataFrame(read(R / 'length_statistics.json')).query(\"variant in ['FULL','MASKED','REVISED']\"))")
    md('## 5. Demonstrate the fit/evaluate boundary\n\nThis cell refits a development LR example and checks it against the completed run. Vocabulary and IDF see only training text. The full experiment runner uses the same estimator function for each fixed intervention. Reproduction commands are in the README; feature extraction is cached, and **final evaluation has an overwrite guard**.')
    code("rows = load_rows()\ntrain = np.array([r['period']=='train' for r in rows])\ny = np.array([r['label'] for r in rows])\ntexts = np.array([r['texts']['MASKED'] for r in rows], dtype=object)\nmodel = estimator('TFIDF_LR', 10.0).fit(texts[train], y[train])\nprediction = model.predict(texts[~train])\nexample = scores(y[~train], prediction)\nsaved = metrics.query(\"experiment=='primary' and model=='TFIDF_LR' and variant=='MASKED'\").iloc[0]\nassert example['confusion_matrix'] == saved.confusion_matrix\nprint(example)")
    md('## 6. Reproduced development results\n\nAll eight original FULL/MASKED model conditions reproduce their saved class predictions exactly. Tiny embedding differences across runtime environments are recorded, rather than described as bit-identical. The validation set has 25 label-0 and 17 label-1 cases, so accuracy and balanced accuracy differ.')
    code("columns = ['model','variant','C','accuracy','balanced_accuracy','macro_f1','recall_0','recall_1','confusion_matrix']\ndisplay(metrics.query(\"experiment=='primary' and variant in ['FULL','MASKED']\")[columns])\ndisplay(pd.DataFrame(read(R / 'verification.json')['reference_prediction_reproduction']))")
    md('## 7. Instructor feedback: matched random removal for LEGAL-BERT\n\nWe independently refit each text variant at the same fixed C, on identical cases. Report all five seeds, not the best seed. The averages below summarize five models, not an ensemble. Both LR and LEGAL-BERT retain substantially more validation performance under random removal than under targeted masking. This argues against word quantity alone explaining the drop, but does not prove that only outcome cues matter.')
    code("display(metrics.query(\"experiment=='primary' and variant.str.startswith('RANDOM')\", engine='python')[columns])\ndisplay(pd.DataFrame(read(R / 'seed_summaries.json')).query(\"experiment=='primary'\"))\ndisplay(Image(filename=str(R / 'figures/controls.png')))")
    md('## 8. Same fitted classifier diagnostic\n\nA separately fitted FULL classifier and MASKED classifier can disagree even when a particular case has identical text. Here the FULL-fitted vectorizer/scaler and coefficients remain fixed while inputs change. This isolates input sensitivity more directly, but creates a distribution shift; it is not the main model ranking.')
    code("display(metrics.query(\"experiment=='same_fitted_FULL' and variant in ['FULL','MASKED']\")[columns])\nlinks = read(R / 'audit_prediction_links.json')\ndisplay(pd.DataFrame([{'case_id':r['case_id'],'mode':r['experiment'],**r['predictions']} for r in links if r['model']=='LEGAL_BERT_LR']))")
    md('## 9. Link changed predictions to passage evidence\n\nThe eight cases were fixed in the earlier audit. We recheck all 22 quoted evidence spans and calculate how much of each quote each random draw removes. These are descriptive case comparisons, not causal explanations of a model\'s internal reasoning. In NY-9301972, FULL equals MASKED and retains an affirmance cue: its refitted-classifier flip disappears with a fixed fitted classifier. NY-5304378 and NY-5957906 still flip under fixed-classifier masking while most random draws remain correct. NY-4929051 behaves differently across refitting modes, illustrating a training effect.')
    code("display(pd.DataFrame(read(R / 'prediction_changes.json')))\nfor case in [r for r in links if r['model']=='LEGAL_BERT_LR' and r['experiment']=='primary']:\n    display(Markdown('**'+case['case_id']+'** — '+case['interpretation']))\n    display(pd.DataFrame([{'quote':e['quote'], **e['fraction_of_quote_words_removed_by_seed']} for e in case['evidence']]))")
    md('## 10. C=1 and controlled masking components\n\nThe 2×2 comparison changes sentence boundaries and the outcome matcher separately, keeping cases and LR C=10 fixed. On this corpus the matcher-only change produces exactly the old texts; combined equals boundary-only. All four targeted conditions have the same validation predictions, despite retention differences. This is evidence that a preprocessing retention improvement need not produce a measurable classifier gain.')
    code("display(metrics.query(\"experiment=='C1_sensitivity'\")[columns])\ndisplay(metrics.query(\"experiment=='components' and not variant.str.contains('RANDOM')\", engine='python')[columns])")
    md('## 11. Approved quality corrections\n\nWe separately test removing the Mann duplicate, refining the mask, and both. Deduplication alone does not change original FULL/MASKED predictions here. REVISED preserves some previously lost context but is not uniformly more accurate. Accuracy was not used to decide whether a clearly mistaken deletion should be repaired.')
    code("display(metrics.query(\"experiment in ['dedup_only','mask_only','dedup_and_mask'] and not variant.str.contains('RANDOM')\", engine='python')[['experiment','n_train']+columns])")
    md('## 12. Length ablation and learning curves\n\nFirst-chunk-only does not show a consistent disadvantage on this small validation set; it can retain opening dispositions in FULL. The eight longest examples contain five reversals, so length and class are confounded. Nested learning curves sample whole training families at 25/50/75/100%, with three fixed seeds and unchanged validation. They do not support a monotonic improvement claim.')
    code("display(metrics.query(\"experiment=='chunk_ablation'\")[columns])\ndisplay(pd.DataFrame(read(R / 'chunk_length_groups.json')))\ndisplay(metrics.query(\"experiment=='learning_curve'\").groupby(['model','fraction']).agg(n_train=('n_train','mean'),mean_BA=('balanced_accuracy','mean'),sd_BA=('balanced_accuracy','std')))")
    md('## 13. Development uncertainty\n\nWe resample validation **families**, preserving pairing across models and conditions, 5,000 times. These percentile intervals are descriptive because validation has been used repeatedly. Seed SD measures deletion randomness; bootstrap intervals measure variation in sampled families conditional on the fitted models. Neither includes uncertainty from relabeling or alternate training sets.')
    code("intervals = pd.DataFrame(read(R / 'paired_intervals.json'))\ndisplay(intervals.query(\"metric=='balanced_accuracy'\")[[ 'comparison','difference','lower','upper']])")
    md('## 14. Reserved test: frozen choices and one evaluation\n\nAfter Yinkui Yu\'s review confirmation, we froze 50 test records and fit on 278 training records only; the 42 validation records were not added to training. Fixed C, seeds, masks and comparisons were recorded before final predictions. Primary FULL/MASKED and matched controls are separate from the secondary REVISED condition. The test has now been evaluated and must not be reused for tuning. Reading these saved outputs is not a new test run.')
    code("v = read(F / 'results/verification.json')\nfor name, expected in v['output_sha256'].items():\n    assert digest((F / 'results' / name).read_bytes()) == expected\nassert digest((F / 'inputs/protocol.json').read_bytes()) == v['protocol_sha256']\ntest_preds = pd.DataFrame(records(F / 'results/predictions.jsonl'))\nfor run, part in test_preds.groupby('run_id'):\n    actual = scores(part.label.to_numpy(), part.prediction.to_numpy())\n    expected = final.set_index('run_id').loc[run]\n    assert actual['confusion_matrix'] == expected.confusion_matrix\ndisplay(final[columns])\ndisplay(Image(filename=str(R / 'figures/test_confusions.png')))")
    md('## 15. Paired final-test uncertainty\n\nAll models use the same 50 test cases. Confidence intervals resample whole test families, with the same draws across conditions. They remain conditional on this selected published-opinion sample, its accepted labels, the fitted training set, and the known masking limitations. Multiple comparisons are exploratory; no best seed or post-test parameter was selected.')
    code("display(pd.DataFrame(read(F / 'results/intervals.json')).query(\"metric=='balanced_accuracy'\"))\ndisplay(pd.DataFrame(read(F / 'results/paired_intervals.json')).query(\"metric=='balanced_accuracy'\"))")
    md('## 16. Conclusions and next steps\n\nThe controlled experiments test information loss, classifier refitting, preprocessing components, duplicate weighting and chunk coverage separately. The strongest development finding is that targeted masking hurts more than quantity-matched random removal. The passage audit shows why this must be described as sensitivity to a mix of outcome cues and legal reasoning.\n\nOn the final test, masked LR, SVM and LEGAL-BERT all have **70% accuracy**, but balanced accuracies differ: **66.36%, 64.71%, 74.63%**. BERT recalls 14/16 reversals but only 21/34 affirmances. Its mean random-minus-mask advantage is **5.74 points**, with a paired interval **[-7.06, 19.31]**; this smaller test gap does not establish the large development effect as stable. LR\'s gap is **10.51 points [2.76, 20.24]**. FULL remains easier, and no definitive model ranking follows from this small selected test set.\n\nNext: document these differing development/test patterns, sample-selection and residual-cue limitations, and finish the project presentation. Do not tune on this test set. Any future mask redesign or new model would need new held-out data for independent evaluation. The original provisional releases remain historical artifacts; the reviewed final release carries the new confirmation record.')
    nb=nbf.v4.new_notebook(cells=cells,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.13'}})
    nbf.write(nb,HERE/'Team_11_Feedback_Experiments.ipynb')
    print('Wrote notebook source; execute_notebook.py saves real cell outputs.')

if __name__=='__main__':main()
